30	// pmFeed delivers msgs in order and returns the model and the last Cmd.
31	func pmFeed(t *testing.T, pm *PathModel, msgs ...tea.Msg) (*PathModel, tea.Cmd) {
32		t.Helper()
33		var cmd tea.Cmd
34		for _, msg := range msgs {
35			pm, cmd = pm.update(msg)
36			if pm == nil {
37				t.Fatal("update returned a nil model")
38			}
39		}
40		return pm, cmd
41	}
42	
43	// launched types target and presses enter.
44	func launched(t *testing.T, pm *PathModel, target string) (*PathModel, tea.Cmd) {
45		t.Helper()
46		pm, _ = pmFeed(t, pm, testutil.Type(target)...)
47		return pmFeed(t, pm, testutil.Key("enter"))
48	}
