50	func pmHopTTLs(pm *PathModel) []int {
51		var out []int
52		for _, h := range pm.table.Items() {
53			out = append(out, h.TTL)
54		}
55		return out
56	}
57	
58	func pmFooter(pm *PathModel, width int) string {
59		return ansi.Strip(pm.footer.View(width, pm.statusLine()))
60	}
61	
62	func headerValue(pm *PathModel, key string) (string, bool) {
63		for _, h := range pm.headerInfo() {
64			if h.Key == key {
65				return h.Value, true
66			}
67		}
68		return "", false
69	}
