75	// Criterion 1 and 6: field and launch key visible, the body is a table even empty.
76	func TestPathNewModelIsAnEditableEmptyTable(t *testing.T) {
77		pm, _ := newPM(t)
78		if !pm.InEditMode() {
79			t.Error("InEditMode() = false on a new Path tab, the target field has the focus")
80		}
81		if pm.running() {
82			t.Error("running() = true before any launch")
83		}
84		if got, want := pm.view(), pm.table.View(); got != want {
85			t.Errorf("view() is not the table view (Rule 139)")
86		}
87		if n := len(pm.table.Items()); n != 0 {
88			t.Errorf("%d rows before any run, want 0", n)
89		}
90		body := ansi.Strip(pm.view())
91		for _, col := range []string{"Hop", "Answer", "Address", "RTT"} {
92			if !strings.Contains(body, col) {
93				t.Errorf("empty table body lacks the %q header:\n%s", col, body)
94			}
95		}
96	}
