179	// Reconciliation: terminal TTL4 after TTL5 cuts the rows; done replaces hops.
180	func TestPathReconciliation(t *testing.T) {
181		pm, _ := newPM(t)
182		pm, _ = launched(t, pm, "1.1.1.1")
183		g := pm.gen
184		pm, _ = pmFeed(t, pm,
185			pathHopMsg{gen: g, hop: hopOf(1, nettrace.HopRouter)},
186			pathHopMsg{gen: g, hop: hopOf(2, nettrace.HopRouter)},
187			pathHopMsg{gen: g, hop: hopOf(3, nettrace.HopRouter)},
188			pathHopMsg{gen: g, hop: hopOf(5, nettrace.HopRouter)},
189		)
190		if got, want := pmHopTTLs(pm), []int{1, 2, 3, 5}; !reflect.DeepEqual(got, want) {
191			t.Fatalf("before the terminal hop: rows = %v, want %v", got, want)
192		}
193		pm, _ = pmFeed(t, pm, pathHopMsg{gen: g, hop: hopOf(4, nettrace.HopTarget)})
194		if got, want := pmHopTTLs(pm), []int{1, 2, 3, 4}; !reflect.DeepEqual(got, want) {
195			t.Fatalf("after the terminal TTL4: rows = %v, want %v", got, want)
196		}
197	
198		final := nettrace.Result{
199			Outcome: nettrace.OutcomeReached,
200			Hops: []nettrace.Hop{
201				hopOf(1, nettrace.HopRouter), hopOf(2, nettrace.HopRouter),
202				hopOf(3, nettrace.HopRouter), hopOf(4, nettrace.HopTarget),
203			},
204		}
205		pm, cmd := pmFeed(t, pm, pathDoneMsg{gen: g, result: final})
206		if !reflect.DeepEqual(pm.hops, final.Hops) {
207			t.Errorf("hops = %v, want Result.Hops %v (replaced at done)", pm.hops, final.Hops)
208		}
209		if cmd != nil {
210			if _, ok := testutil.MsgOf[pathHopMsg](cmd); ok {
211				t.Error("done re-armed the wait Cmd")
212			}
213		}
214		if pm.running() || pm.InEditMode() {
215			t.Errorf("after done: running=%v InEditMode=%v, want a done state with the field blurred", pm.running(), pm.InEditMode())
216		}
217		if v, ok := headerValue(pm, "Path"); !ok || v != "Reached at hop 4" {
218			t.Errorf("Path header = %q (%v), want %q", v, ok, "Reached at hop 4")
219		}
220		if pm.statusLine().Activity {
221			t.Error("status still shows activity once done")
222		}
223		if pm.result == nil {
224			t.Fatal("result is nil after a done message")
225		}
226	}
