228	// Criterion 3.
229	func TestPathUnresolvedNameIsAPersistentFooterError(t *testing.T) {
230		pm, _ := newPM(t)
231		pm, _ = launched(t, pm, "nope.invalid")
232		g := pm.gen
233		pm, _ = pmFeed(t, pm, pathDoneMsg{gen: g, err: fmt.Errorf("%w: %w", errPathResolve, errors.New("no such host"))})
234	
235		if pm.running() || !pm.InEditMode() {
236			t.Errorf("running=%v InEditMode=%v, want editing with the field focused", pm.running(), pm.InEditMode())
237		}
238		if n := len(pm.table.Items()); n != 0 {
239			t.Errorf("%d rows after a resolve failure, want none", n)
240		}
241		st := pm.statusLine()
242		want := "Could not resolve nope.invalid — no probe was sent"
243		if st.Level != components.LevelError || st.Text != want {
244			t.Errorf("status = {%v %q}, want Error %q", st.Level, st.Text, want)
245		}
246		if line := pmFooter(pm, 100); !strings.Contains(line, want) {
247			t.Errorf("rendered footer = %q, want %q", line, want)
248		}
249		// Persistent: not a 3 s message, it survives a footer expiry.
250		pm, _ = pmFeed(t, pm, components.ClearFooterMsg{ID: pm.footer.ID()})
251		if pm.statusLine().Text != want {
252			t.Errorf("the error vanished with the footer timer: %+v", pm.statusLine())
253		}
254		// A change of the field clears it.
255		pm, _ = pmFeed(t, pm, testutil.Key("x"))
256		if pm.statusLine().Level == components.LevelError {
257			t.Errorf("typing did not clear the error: %+v", pm.statusLine())
258		}
259	}
