261	func TestPathLaunchRefusals(t *testing.T) {
262		tests := []struct {
263			name, input, want string
264		}{
265			{"empty", "", "Target is required"},
266			{"ipv6", "::1", "Only IPv4 targets are supported by the path trace"},
267			{"port zero", "h:0", "Port must be a number between 1 and 65535"},
268		}
269		for _, tc := range tests {
270			t.Run(tc.name, func(t *testing.T) {
271				pm, f := newPM(t)
272				gen := pm.gen
273				pm, _ = pmFeed(t, pm, testutil.Type(tc.input)...)
274				pm, _ = pmFeed(t, pm, testutil.Key("enter"))
275				if pm.gen != gen || pm.running() || !pm.InEditMode() {
276					t.Errorf("gen=%d running=%v edit=%v, want unchanged editing", pm.gen, pm.running(), pm.InEditMode())
277				}
278				if pm.footer.Level() != components.LevelError || pm.footer.Text() != tc.want {
279					t.Errorf("footer = {%v %q}, want Error %q", pm.footer.Level(), pm.footer.Text(), tc.want)
280				}
281				if f.resolveCalls != 0 || f.traceCalls != 0 {
282					t.Errorf("engine called (%d resolve, %d trace) on an invalid target", f.resolveCalls, f.traceCalls)
283				}
284			})
285		}
286	}
