503		pm, _ = launched(t, pm, "1.1.1.1")
504		pm, _ = pmFeed(t, pm, testutil.Key("esc"))
505		if pm.result == nil {
506			t.Fatal("result nil after cancel")
507		}
508		_ = pm.headerInfo()
509	}
510	
511	// Rule 110: launching builds a Cmd without touching the model; the stored
512	// context is live until cancel.
513	func TestPathLaunchStoresALiveContextAndChannel(t *testing.T) {
514		pm, _ := newPM(t)
515		pm, _ = launched(t, pm, "1.1.1.1")
516		if pm.cancel == nil || pm.msgs == nil {
517			t.Fatalf("cancel=%v msgs=%v, want both stored while running", pm.cancel != nil, pm.msgs != nil)
