338		if !cancelled {
339			t.Error("esc did not call the run's cancel func")
340		}
341		if pm.running() {
342			t.Error("running() = true right after esc: the UI must answer at once")
343		}
344		if pm.gen == oldGen {
345			t.Error("gen not bumped on esc, late messages would be accepted")
346		}
347		if pm.result == nil || pm.result.Outcome != nettrace.OutcomeCancelled {
348			t.Errorf("result = %+v, want a Cancelled outcome", pm.result)
349		}
350		if got, want := pmHopTTLs(pm), []int{1}; !reflect.DeepEqual(got, want) {
351			t.Errorf("rows after cancel = %v, want %v kept", got, want)
352		}
353		if v, _ := headerValue(pm, "Path"); v != "Canceled" {
354			t.Errorf("Path header = %q, want Canceled", v)
355		}
356	
357		// Late messages of the old run change nothing and are not re-armed.
358		before := pmHopTTLs(pm)
359		var cmd tea.Cmd
360		pm, cmd = pmFeed(t, pm, pathHopMsg{gen: oldGen, hop: hopOf(2, nettrace.HopRouter)})
361		if cmd != nil {
362			t.Error("a stale hop re-armed the wait Cmd")
363		}
364		pm, cmd = pmFeed(t, pm, pathDoneMsg{gen: oldGen, result: nettrace.Result{Outcome: nettrace.OutcomeReached}})
365		if cmd != nil {
366			t.Error("a stale done returned a Cmd")
367		}
368		if !reflect.DeepEqual(pmHopTTLs(pm), before) || pm.result.Outcome != nettrace.OutcomeCancelled {
369			t.Errorf("a stale message changed the model: rows %v, result %+v", pmHopTTLs(pm), pm.result)
370		}
371	
372		// The UI is usable: enter starts a new run on the same target.
373		gen := pm.gen
374		pm, cmd = pmFeed(t, pm, testutil.Key("enter"))
375		if cmd == nil || !pm.running() || pm.gen != gen+1 {
376			t.Errorf("relaunch after cancel: cmd=%v running=%v gen=%d, want a run with gen %d", cmd != nil, pm.running(), pm.gen, gen+1)
377		}
378	}
379	
380	func TestPathStaleGenerationHopIsDropped(t *testing.T) {
381		pm, _ := newPM(t)
382		pm, _ = launched(t, pm, "1.1.1.1")
383		pm, cmd := pmFeed(t, pm, pathHopMsg{gen: pm.gen - 1, hop: hopOf(1, nettrace.HopRouter)})
384		if cmd != nil || len(pm.table.Items()) != 0 {
385			t.Errorf("stale hop: cmd=%v rows=%d, want ignored", cmd != nil, len(pm.table.Items()))
386		}
387	}
388	
389	func TestPathRunningIgnoresTypingAndPaste(t *testing.T) {
390		pm, _ := newPM(t)
391		pm, _ = launched(t, pm, "1.1.1.1")
392		before := pm.input.Value()
393		pm, _ = pmFeed(t, pm, testutil.Key("x"), testutil.Paste("evil"))
394		if got := pm.input.Value(); got != before {
395			t.Errorf("field = %q while running, want %q", got, before)
396		}
397	}
398	
399	func TestPathPasteReachesTheFieldWhileEditing(t *testing.T) {
400		pm, _ := newPM(t)
401		pm, _ = pmFeed(t, pm, testutil.Paste("example.com"))
402		if got := pm.input.Value(); got != "example.com" {
403			t.Errorf("field = %q after a paste, want example.com", got)
404		}
405		if pm.running() {
406			t.Error("a paste launched a trace")
407		}
408	}
409	
410	func TestPathDoneEnterRelaunchesAndEscEdits(t *testing.T) {
411		pm, _ := newPM(t)
412		pm, _ = launched(t, pm, "1.1.1.1:443")
413		g := pm.gen
414		pm, _ = pmFeed(t, pm, pathDoneMsg{gen: g, result: nettrace.Result{
415			Outcome: nettrace.OutcomeReached, Hops: []nettrace.Hop{hopOf(1, nettrace.HopTarget)},
416		}})
417	
418		if v, _ := headerValue(pm, "Target"); !strings.Contains(v, "1.1.1.1:443") {
419			t.Errorf("Target header = %q, want the host:port", v)
420		}
421		if !testutil.ShortcutEnabled(pm.shortcuts(), "enter") || !testutil.HasShortcut(pm.shortcuts(), "esc") {
422			t.Errorf("done shortcuts = %v, want enter and esc", testutil.ShortcutKeys(pm.shortcuts()))
423		}
424	
425		again, cmd := pmFeed(t, pm, testutil.Key("enter"))
426		if cmd == nil || !again.running() || again.gen != g+1 || again.target != (pathTarget{Host: "1.1.1.1", Port: 443}) {
427			t.Errorf("relaunch: cmd=%v running=%v gen=%d target=%v", cmd != nil, again.running(), again.gen, again.target)
428		}
429	
430		edit, _ := pmFeed(t, pm, testutil.Key("esc"))
431		if !edit.InEditMode() || edit.input.Value() != "1.1.1.1:443" {
432			t.Errorf("esc from done: edit=%v value=%q, want editing with the value kept", edit.InEditMode(), edit.input.Value())
433		}
434		if len(edit.table.Items()) != 1 {
435			t.Errorf("rows after esc from done = %d, want hops kept until the next launch", len(edit.table.Items()))
436		}
437	}
438	
439	// Rule 130: the key set is the same in every state of one screen, except the
440	// running mode that replaces the list.
441	func TestPathShortcutsPerState(t *testing.T) {
442		pm, _ := newPM(t)
443		if !testutil.HasShortcut(pm.shortcuts(), "tab") {
444			t.Error("editing lacks tab")
445		}
446		run, _ := launched(t, pm, "1.1.1.1")
447		if !testutil.ShortcutEnabled(run.shortcuts(), "esc") {
448			t.Errorf("running shortcuts = %v, want esc", testutil.ShortcutKeys(run.shortcuts()))
449		}
450		for _, s := range run.shortcuts() {
451			if s.Key == "esc" && s.Description != "Cancel the trace" {
452				t.Errorf("running esc = %q, want Cancel the trace", s.Description)
453			}
454		}
455	}
456	
457	// Criterion 6, Rules 128/139: the body is the table in every state and the
458	// footer slot has a fixed height.
459	func TestPathBodyIsTheTableAndFooterHeightIsFixed(t *testing.T) {
460		idle, _ := newPM(t)
461		run, _ := launched(t, mustPM(t), "1.1.1.1")
462		done, _ := pmFeed(t, run, pathDoneMsg{gen: run.gen, result: nettrace.Result{Outcome: nettrace.OutcomeReached}})
463		failed, _ := pmFeed(t, mustPM(t), testutil.Key("enter"))
464	
465		wantBar := strings.Count(idle.barView(100), "\n")
466		for name, pm := range map[string]*PathModel{"idle": idle, "running": run, "done": done, "refused": failed} {
467			if got, want := pm.view(), pm.table.View(); got != want {
468				t.Errorf("%s: view() is not the table view", name)
469			}
470			if got := strings.Count(pm.barView(100), "\n"); got != wantBar {
471				t.Errorf("%s: bar has %d line breaks, want %d (constant footer height)", name, got, wantBar)
472			}
473			if got := strings.Count(pmFooter(pm, 100), "\n"); got != 0 {
474				t.Errorf("%s: message line has %d line breaks, want a single line", name, got)
475			}
476		}
477	}
478	
479	func mustPM(t *testing.T) *PathModel {
480		t.Helper()
481		pm, _ := newPM(t)
482		return pm
483	}
484	
485	// Rule 116.
486	func TestPathTableFillsTheViewport(t *testing.T) {
487		for _, w := range []int{120, 60} {
488			pm, _ := newPM(t)
489			pm.resize(w, 30)
490			if got, want := pm.table.RenderedWidth(), w-2; got != want {
491				t.Errorf("width %d: RenderedWidth() = %d, want %d", w, got, want)
492			}
493		}
494	}
495	
496	// A done message always carries a usable Result: a cancel leaves one, and the
497	// header never reads a nil result.
498	func TestPathHeaderNeverReadsANilResult(t *testing.T) {
499		pm, _ := newPM(t)
500		if _, ok := headerValue(pm, "Path"); ok {
501			t.Error("a Path header before any run")
502		}
503		pm, _ = launched(t, pm, "1.1.1.1")
504		pm, _ = pmFeed(t, pm, testutil.Key("esc"))
505		if pm.result == nil {
506			t.Fatal("result nil after cancel")
507		}
508		_ = pm.headerInfo()
509	}
510	
511	// Rule 110: launching builds a Cmd without touching the model; the stored
512	// context is live until cancel.
513	func TestPathLaunchStoresALiveContextAndChannel(t *testing.T) {
514		pm, _ := newPM(t)
515		pm, _ = launched(t, pm, "1.1.1.1")
516		if pm.cancel == nil || pm.msgs == nil {
517			t.Fatalf("cancel=%v msgs=%v, want both stored while running", pm.cancel != nil, pm.msgs != nil)
518		}
519	}
