1	package netdiag
2	
3	import (
4		"context"
5		"fmt"
6		"log"
7		"net"
8		"net/netip"
9		"time"
10	
11		tea "charm.land/bubbletea/v2"
12	
13		"github.com/anthnel/devdesk/internal/nettrace"
14	)
15	
16	// pathChanCap holds a whole trace: every hop (at most MaxHopsLimit), the
17	// resolved message and the done message. The producer therefore never waits
18	// for a reader.
19	const pathChanCap = nettrace.MaxHopsLimit + 2
20	
21	// pathEngine is the seam between the path tab and the network: tests replace
22	// it with a fake.
23	type pathEngine struct {
24		supported func() error
25		resolve   func(ctx context.Context, host string) ([]netip.Addr, error)
26		trace     func(ctx context.Context, a netip.Addr, o nettrace.Options, onHop func(nettrace.Hop)) (nettrace.Result, error)
27	}
28	
29	// systemPathEngine returns the engine backed by the real resolver and sockets.
30	//
31	//nolint:unused // wired by the path model (DEVDESK-328 step 4)
32	func systemPathEngine() pathEngine {
33		return pathEngine{
34			supported: nettrace.Supported,
35			resolve: func(ctx context.Context, host string) ([]netip.Addr, error) {
36				return net.DefaultResolver.LookupNetIP(ctx, "ip4", host)
37			},
38			trace: nettrace.TraceEach,
39		}
40	}
41	
42	// pathResolvedMsg reports the address the target resolved to.
43	type pathResolvedMsg struct {
44		gen  int
45		addr netip.Addr
46	}
47	
48	// pathHopMsg carries one hop as the engine reports it.
49	type pathHopMsg struct {
50		gen int
51		hop nettrace.Hop
52	}
53	
54	// pathDoneMsg ends a run: a result, or an error when no trace happened.
55	type pathDoneMsg struct {
56		gen    int
57		result nettrace.Result
58		err    error
59	}
60	
61	// producePath resolves the target, traces it and sends the messages to out,
62	// then closes out. It runs inside a Cmd and touches no model (Rule 110).
63	// out must have room for pathChanCap messages: sends never block, so a view
64	// that stops reading after canceling leaks nothing.
65	func producePath(ctx context.Context, gen int, tg pathTarget, resolveTimeout time.Duration, e pathEngine, out chan<- tea.Msg) {
66		defer close(out)
67		send := func(m tea.Msg) {
68			select {
69			case out <- m:
70			default:
71			}
72		}
73	
74		addr, err := resolvePathTarget(ctx, tg.Host, resolveTimeout, e)
75		if err != nil {
76			log.Printf("ERROR [netdiag/path] resolve %s: %v", tg.Host, err)
77			send(pathDoneMsg{gen: gen, err: err})
78			return
79		}
80		send(pathResolvedMsg{gen: gen, addr: addr})
81	
82		res, err := e.trace(ctx, addr, nettrace.Options{}, func(h nettrace.Hop) {
83			send(pathHopMsg{gen: gen, hop: h})
84		})
85		if err != nil {
86			log.Printf("ERROR [netdiag/path] trace %s: %v", tg.Host, err)
87		}
88		send(pathDoneMsg{gen: gen, result: res, err: err})
89	}
90	
91	// resolvePathTarget returns the IPv4 address to trace: a literal is used as
92	// is, a name is resolved under its own timeout.
93	func resolvePathTarget(ctx context.Context, host string, timeout time.Duration, e pathEngine) (netip.Addr, error) {
94		if a, err := netip.ParseAddr(host); err == nil && a.Is4() {
95			return a, nil
96		}
97		rctx, cancel := context.WithTimeout(ctx, timeout)
98		defer cancel()
99		addrs, err := e.resolve(rctx, host)
100		if err != nil {
101			return netip.Addr{}, fmt.Errorf("%w: %w", errPathResolve, err)
102		}
103		if len(addrs) == 0 {
104			return netip.Addr{}, errPathNoIPv4
105		}
106		return addrs[0], nil
107	}
108	
109	// waitForPathMsg returns a Cmd that yields the next message of in, or nil
110	// once in is closed. The view re-arms it after every message.
111	func waitForPathMsg(in <-chan tea.Msg) tea.Cmd {
112		return func() tea.Msg {
113			m, ok := <-in
114			if !ok {
115				return nil
116			}
117			return m
118		}
119	}
