1	package netdiag
2	
3	import (
4		"context"
5		"fmt"
6		"log"
7		"strconv"
8		"time"
9	
10		tea "charm.land/bubbletea/v2"
11		"charm.land/lipgloss/v2"
12	
13		"github.com/anthnel/devdesk/internal/netiface"
14		"github.com/anthnel/devdesk/internal/ui/components"
15		"github.com/anthnel/devdesk/internal/ui/datatable"
16		"github.com/anthnel/devdesk/internal/ui/theme"
17	)
18	
19	// ifaceDataMsg carries one read of this machine's interfaces.
20	type ifaceDataMsg struct {
21		interfaces []netiface.Interface
22		err        error
23	}
24	
25	// ifaceFetchTimeout bounds one read. The interfaces are a system call and the
26	// counters are another; neither waits on the network, so this is a backstop
27	// against a wedged platform call rather than a budget anything is expected to
28	// approach.
29	const ifaceFetchTimeout = 5 * time.Second
30	
31	// NewInterfacesDataMsg hands interface rows to the Interfaces tab without
32	// reading the machine (guard seed, DEVDESK-373).
33	func NewInterfacesDataMsg(ifaces []netiface.Interface) tea.Msg {
34		return ifaceDataMsg{interfaces: ifaces}
35	}
36	
37	func fetchInterfacesCmd() tea.Cmd {
38		return func() tea.Msg {
39			ctx, cancel := context.WithTimeout(context.Background(), ifaceFetchTimeout)
40			defer cancel()
41			ifaces, err := netiface.List(ctx)
42			return ifaceDataMsg{interfaces: ifaces, err: err}
43		}
44	}
45	
46	// InterfacesModel is the tab that lists this machine's network interfaces.
47	//
48	// It was the Topology tab, which showed four sections read from ip and
49	// iptables in containers started with --network host — that is, the Docker
50	// Desktop VM's network and not the machine's (D57). Three of the four sections
51	// were removed rather than translated, because nothing portable produces them
52	// (§3.44); the route question moved to the Diagnostics pipeline, where it is
53	// asked about a target rather than in the abstract. What is left is what reads
54	// natively everywhere, so the tab is named after it.
55	type InterfacesModel struct {
56		width  int
57		height int
58	
59		table datatable.Model[netiface.Interface]
60	
61		loading bool
62		// lastOK dates the rows, and loadErr says the most recent read failed.
63		//
64		// A failed read keeps the rows on screen: they are not wrong, they are
65		// dated, and dropping them would leave the tab empty over a transient
66		// failure. What has to be said is their age — a footer *message* cannot
67		// carry it, since it expires after three seconds (Rule 128).
68		lastOK  time.Time
69		loadErr bool
70	
71		// footer is this tab's own message line. Each tab keeps one: a shared
72		// instance would let a message set here outlive the switch away from it.
73		footer components.FooterMessage
74	}
75	
76	func newInterfacesModel() *InterfacesModel {
77		return &InterfacesModel{
78			loading: true,
79			table: datatable.New(datatable.Config[netiface.Interface]{
80				Columns:    interfaceColumns(),
81				SortColumn: 0,
82			}),
83		}
84	}
85	
86	// interfaceColumns describes the interfaces table.
87	//
88	// The MAC is here because net.Interfaces() hands it over for nothing and the
89	// old tab threw it away — it is what a DHCP lease, a switch port and an asset
90	// inventory are all keyed on, so it is the field someone comes to this screen
91	// to copy.
92	func interfaceColumns() []datatable.Column[netiface.Interface] {
93		name := datatable.Column[netiface.Interface]{
94			Title: "Interface", Sizing: datatable.SizingContent, MinWidth: 16,
95			Cell:   func(i netiface.Interface) string { return i.Name },
96			Search: func(i netiface.Interface) string { return i.Name },
97			Less:   func(a, b netiface.Interface) bool { return a.Name < b.Name },
98		}
99		state := datatable.Column[netiface.Interface]{
100			Title: "State", Sizing: datatable.SizingFixed, MinWidth: 7,
101			Cell:  func(i netiface.Interface) string { return i.State },
102			Style: interfaceStateStyle,
103			Less:  func(a, b netiface.Interface) bool { return a.State < b.State },
104		}
105		mtu := datatable.Column[netiface.Interface]{
106			Title: "MTU", Sizing: datatable.SizingFixed, Optional: true, MinWidth: 6,
107			Cell: func(i netiface.Interface) string {
108				if !i.HasMTU() {
109					return "-"
110				}
111				return strconv.Itoa(i.MTU)
112			},
113			Style: func(i netiface.Interface) lipgloss.Style {
114				if !i.HasMTU() {
115					return theme.DimStyle
116				}
117				return lipgloss.Style{}
118			},
119			Less: func(a, b netiface.Interface) bool { return a.MTU < b.MTU },
120		}
121		mac := datatable.Column[netiface.Interface]{
122			Title: "MAC", Sizing: datatable.SizingFixed, Optional: true, MinWidth: 17,
123			Cell:   macOrDash,
124			Search: func(i netiface.Interface) string { return i.MAC },
125			Style: func(i netiface.Interface) lipgloss.Style {
126				if i.MAC == "" {
127					return theme.DimStyle
128				}
129				return lipgloss.Style{}
130			},
131		}
132		rx := errorColumn("RX err", func(i netiface.Interface) *uint64 { return i.RxErrors })
133		tx := errorColumn("TX err", func(i netiface.Interface) *uint64 { return i.TxErrors })
134		// Both address columns follow their content and both carry a flex weight.
135		// The flex is what levels them against each other when there is a shortfall
136		// — a table reclaims from the widest content column first, so with the flex
137		// on IPv6 alone it used to absorb the whole shortfall and render at zero
138		// width from about 100 columns down, header included. IPv6 asks for more
139		// and grows faster because its notation is longer.
140		//
141		// Squeezed to nothing is no longer one of the outcomes (§3.45): MinWidth is
142		// a floor, and what gives way past it is a whole column, MTU / MAC / the
143		// two counters first because they are the ones marked Optional here.
144		v4 := addressColumn("IPv4", minIPv4Width, 1, netiface.Interface.IPv4List)
145		v6 := addressColumn("IPv6", minIPv6Width, 2, netiface.Interface.IPv6List)
146	
