90	// inventory are all keyed on, so it is the field someone comes to this screen
91	// to copy.
92	func interfaceColumns() []datatable.Column[netiface.Interface] {
93		name := datatable.Column[netiface.Interface]{
94			Title: "Interface", Sizing: datatable.SizingContent, MinWidth: 16,
95			Cell:   func(i netiface.Interface) string { return i.Name },
96			Search: func(i netiface.Interface) string { return i.Name },
97			Less:   func(a, b netiface.Interface) bool { return a.Name < b.Name },
98		}
99		state := datatable.Column[netiface.Interface]{
100			Title: "State", Sizing: datatable.SizingFixed, MinWidth: 7,
101			Cell:  func(i netiface.Interface) string { return i.State },
102			Style: interfaceStateStyle,
103			Less:  func(a, b netiface.Interface) bool { return a.State < b.State },
104		}
105		mtu := datatable.Column[netiface.Interface]{
106			Title: "MTU", Sizing: datatable.SizingFixed, Optional: true, MinWidth: 6,
107			Cell: func(i netiface.Interface) string {
108				if !i.HasMTU() {
109					return "-"
110				}
111				return strconv.Itoa(i.MTU)
112			},
113			Style: func(i netiface.Interface) lipgloss.Style {
114				if !i.HasMTU() {
