122			Title: "MAC", Sizing: datatable.SizingFixed, Optional: true, MinWidth: 17,
123			Cell:   macOrDash,
124			Search: func(i netiface.Interface) string { return i.MAC },
125			Style: func(i netiface.Interface) lipgloss.Style {
126				if i.MAC == "" {
127					return theme.DimStyle
128				}
129				return lipgloss.Style{}
130			},
131		}
132		rx := errorColumn("RX err", func(i netiface.Interface) *uint64 { return i.RxErrors })
133		tx := errorColumn("TX err", func(i netiface.Interface) *uint64 { return i.TxErrors })
134		// Both address columns follow their content and both carry a flex weight.
135		// The flex is what levels them against each other when there is a shortfall
136		// — a table reclaims from the widest content column first, so with the flex
137		// on IPv6 alone it used to absorb the whole shortfall and render at zero
138		// width from about 100 columns down, header included. IPv6 asks for more
139		// and grows faster because its notation is longer.
