198	// macOrDash renders the hardware address, or says it has none.
199	//
200	// A loopback and a tunnel have no MAC, which is a fact about them rather than a
201	// missing reading — and an empty cell would look like the second.
202	func macOrDash(i netiface.Interface) string {
203		if i.MAC == "" {
204			return "-"
205		}
206		return i.MAC
207	}
208	
209	// errorColumn builds one of the two counter columns.
210	//
211	// The dash is D58 in a cell: the counters come from a source that fails on its
212	// own, and a zero written because nobody looked reads as an interface with no
213	// errors. So nil prints "-" and never "0", and the dash is dim because an
214	// absent reading is not a value worth spotting — a non-zero count is.
215	//
216	// This is the raw counter, since boot, per interface. The dashboard's
217	// Network box (§3.70) shows the same field aggregated across every
218	// interface and windowed since DevDesk started watching, not since boot —
219	// the two numbers are not meant to agree, and neither is a rollup of the
220	// other.
221	func errorColumn(title string, get func(netiface.Interface) *uint64) datatable.Column[netiface.Interface] {
222		return datatable.Column[netiface.Interface]{
223			Title: title, Sizing: datatable.SizingFixed, Optional: true, MinWidth: 8,
224			Cell: func(i netiface.Interface) string {
225				n := get(i)
226				if n == nil {
227					return "-"
228				}
229				return strconv.FormatUint(*n, 10)
230			},
231			Style: func(i netiface.Interface) lipgloss.Style {
232				n := get(i)
233				if n == nil || *n == 0 {
234					return theme.DimStyle
235				}
236				return theme.StatusWarningStyle
237			},
238			Less: func(a, b netiface.Interface) bool {
239				return errorCount(get(a)) < errorCount(get(b))
240			},
241		}
242	}
243	
244	// errorCount orders a counter for the sort. An unread counter sorts below zero
245	// so that descending — the direction anyone sorting this column wants — puts
246	// the interfaces that actually dropped frames on top, and never a row nobody
247	// managed to read.
248	func errorCount(n *uint64) int64 {
249		if n == nil {
250			return -1
251		}
252		return int64(*n)
253	}
