336	// Staleness outranks the load: a read that failed makes the rows on screen
337	// dated, and that has to keep being said while the next one runs.
338	func (im *InterfacesModel) statusLine() components.Status {
339		if im.loadErr {
340			return components.Status{Text: im.staleLabel(), Level: components.LevelError}
341		}
342		if im.loading {
343			return components.Status{Text: "Reading network interfaces...", Activity: true}
344		}
345		return components.Status{}
346	}
