349	func (im *InterfacesModel) staleLabel() string {
350		if im.lastOK.IsZero() {
351			return "The network interfaces could not be read"
352		}
353		return "The network interfaces could not be read — interfaces as of " + theme.TimeAgo(im.lastOK)
354	}
