365	func (im *InterfacesModel) summaryLine() string {
366		up := 0
367		for _, i := range im.table.Items() {
368			if i.State == netiface.StateUp {
369				up++
370			}
371		}
372		return fmt.Sprintf("%d up / %d total", up, len(im.table.Items()))
373	}
