	theme.StyleTextInput(&portIn)
	portIn.Placeholder = defaultPort
	portIn.CharLimit = 10

	dnsIn := textinput.New()
	theme.StyleTextInput(&dnsIn)
	// Empty means the system resolver, and that is the answer the user cares
	// about: it is the one their own traffic uses. The old default read the
	// first nameserver out of /etc/resolv.conf, which does not exist on Windows.
	dnsIn.Placeholder = "system resolver"
	dnsIn.CharLimit = 64
		return m.renderChecks()
	case StateDetails:
		return m.detailsViewport.View()
	}
	return ""
}

func (m *Model) renderInputForm() string {
	var b strings.Builder

	b.WriteString(m.renderTextInputField("Target", m.targetInput, fieldTarget))
	b.WriteString("\n")
	b.WriteString(m.renderTextInputField("Port", m.portInput, fieldPort))
	b.WriteString("\n")
	b.WriteString(m.renderTextInputField("DNS Server", m.dnsServerInput, fieldDNSServer))
	b.WriteString("\n\n")
	b.WriteString("  " + theme.RenderButton("Run Diagnostics", m.focusedField == fieldButton, "primary"))

	return lipgloss.NewStyle().
		Padding(1).
		Background(theme.ColorBackground).
		Render(b.String())
}

func (m *Model) renderTextInputField(label string, input textinput.Model, fieldIdx int) string {
	prefix := "  "
	if m.focusedField == fieldIdx {
		prefix = theme.IconCircleSmall + " "
	}
	return theme.KeyStyle.Render(prefix+label+" "+theme.IconChevronRight+" ") + input.View()
}

// renderChecks draws the results table. An empty table — the run produced
// none, or the "problems" filter hid every one because they all passed —
// stays a table (Rule 139): its header and no rows. The Verdict header field
// already answers "did everything pass?" once there is a run to summarise.
func (m *Model) renderChecks() string {
	return m.checksTable.View()
}

// checkColumns describes the results table.
// two lines here are the sides and the floor:
//
//	│  / cursor...                    Aa │
//	└────────────────────────────────────┘
//
// It is shared rather than copied because two things now occupy that one slot —
// the filter bar and the viewer's go-to-line prompt — and a second
// implementation of the frame would be free to disagree with the first about
// where the corners are. `inner` is already styled; it is padded to the width
// between the sides, so a caller measures nothing.
func BarFrame(width int, inner string) string {
	if width == 0 {
		width = 80
	}

	borderStyle := lipgloss.NewStyle().Foreground(theme.ColorViewportBorder).Background(theme.ColorBackground)

	// width-2 to leave room for │ on each side.
	padded := theme.PadWithBg(inner, width-2)
	content := borderStyle.Render("│") + padded + borderStyle.Render("│")
	bottom := borderStyle.Render("└" + strings.Repeat("─", width-2) + "┘")
	return content + "\n" + bottom
}
